package com.scamshield.provider; import com.scamshield.common.repo.*; import org.springframework.web.bind.annotation.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api/providers") public class ProviderController { private final ProviderRepository providers; private final OfficialNumberRepository numbers; public ProviderController(ProviderRepository p,OfficialNumberRepository n){providers=p;numbers=n;} @GetMapping public Object all(){return providers.findAll();} @GetMapping("/{id}/official-numbers") public Object nums(@PathVariable Long id){return numbers.findByProviderId(id);} }
